<?php $rows=qall('SELECT * FROM shipping_methods ORDER BY cost'); ?>
<div class="erp-grid"><section class="erp-card"><div class="erp-card-head"><div><h2>Zona Pengiriman</h2><p>Buat zona berdasarkan jarak/area tujuan (mis. Dalam kota, Jabodetabek, Luar pulau). Zona aktif langsung tersedia di checkout.</p></div></div><form method="post" class="erp-form"><input type="hidden" name="action" value="admin_shipping_save"><input type="hidden" name="csrf" value="<?= e(compliance_csrf()) ?>"><label>Nama metode<input name="name" maxlength="100" required></label><label>Biaya (Rp)<input type="number" name="cost" min="0" required></label><label>Estimasi<input name="eta" maxlength="100" placeholder="2–4 hari"></label><label class="management-check"><input type="checkbox" name="is_active" checked> Aktif di checkout</label><button class="erp-btn">Simpan metode</button></form></section><section class="erp-card erp-wide"><div class="erp-table-wrap"><table><thead><tr><th>Zona</th><th>Ongkir</th><th>Estimasi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $x): ?><tr><td><?= e($x['name']) ?></td><td><?= rupiah($x['cost']) ?></td><td><?= e($x['eta']) ?></td><td><?= $x['is_active']?'Aktif':'Nonaktif' ?></td><td><form method="post"><input type="hidden" name="action" value="admin_shipping_delete"><input type="hidden" name="csrf" value="<?= e(compliance_csrf()) ?>"><input type="hidden" name="id" value="<?= (int)$x['id'] ?>"><button class="erp-link-danger">Hapus</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></div>
